    function testRegression_property() public {
        address nonCreator = address(0x1234);
        vm.deal(nonCreator, 1 ether);
        vm.prank(nonCreator);
        bool ok;
        try c.migrateTo(address(0x5678)) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
